package local.pocketchat;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.function.Consumer;
import org.json.*;

/** Whole production controller/store/profile, real files and declared native callback inputs. */
public final class ControllerHost {
  static Path root;static final List<String> checks=new ArrayList<>();
  interface Work{void run()throws Exception;}
  static void check(String name,boolean ok){if(!ok)throw new AssertionError(name);checks.add(name);}
  static void rejects(String name,Work work)throws Exception{boolean failed=false;try{work.run();}catch(Exception expected){failed=true;}check(name,failed);}
  static byte[] bytes(String text){return text.getBytes(StandardCharsets.UTF_8);}
  static final String CLOSED="prefs:\n  network.proxy.socks: '127.0.0.1'\n  network.proxy.socks_port: 9\n  dom.maxHardwareConcurrency: 2\n  privacy.resistFingerprinting: true\n";
  static void base(Path path)throws Exception{Files.createDirectories(path);Files.write(path.resolve("gecko-browser.yaml"),bytes(CLOSED));}
  static void profile()throws Exception{
    String original="// Mozilla User Preferences\r\nuser_pref(\"privacy.resistFingerprinting\", true);\r\nuser_pref(\"security.tls.version.min\", 4);\r\nuser_pref(\"dom.maxHardwareConcurrency\", 2);\r\nuser_pref(\"security.tls.version.max\", 4);\nuser_pref(\"other\", \"中文\\\"value\");";
    String expected=original.replace("user_pref(\"security.tls.version.min\", 4);\r\n","").replace("user_pref(\"security.tls.version.max\", 4);\n","");
    check("Only both TLS USER lines removed; unrelated CPU/RFP/UTF8/CRLF bytes preserved",Arrays.equals(GeckoTlsProfile.withoutTls(bytes(original)),bytes(expected)));
    check("Absent owned TLS keys preserve complete bytes",Arrays.equals(GeckoTlsProfile.withoutTls(bytes(expected)),bytes(expected)));
    check("No final newline remains unchanged",Arrays.equals(GeckoTlsProfile.withoutTls(bytes("user_pref(\"other\", 7);")),bytes("user_pref(\"other\", 7);")));
    for(String bad:new String[]{"user_pref(\"security.tls.version.min\", 3);\nuser_pref(\"security.tls.version.min\", 4);","user_pref(\"security.tls.version.max\", true);","pref(\"security.tls.version.min\", 4);","user_pref(\"security.tls.version.\\u006din\", 4);","user_pref(\"other\", 1);user_pref(\"security.tls.version.min\", 4);","// security.tls.version.max"})rejects("Ambiguous/duplicate/escaped or executable TLS preference rejected",()->GeckoTlsProfile.withoutTls(bytes(bad)));
    String huge="user_pref(\"unrelated\", \""+String.join("",Collections.nCopies(200000,"x"))+"\");\n";check("Large single preference stays linear and byte preserved",Arrays.equals(GeckoTlsProfile.withoutTls(bytes(huge)),bytes(huge)));
    rejects("Malformed UTF8 rejected without normalization",()->GeckoTlsProfile.withoutTls(new byte[]{(byte)0xc3,0x28}));rejects("Over4MiB rejected",()->GeckoTlsProfile.withoutTls(new byte[GeckoTlsProfile.MAX_BYTES+1]));
    Path path=root.resolve("profile");base(path);File profile=path.resolve("gecko-browser").toFile();GeckoTlsProfile.prepare(path.toFile(),profile,GeckoTlsSpec.defaults());Path prefs=profile.toPath().resolve("prefs.js");Files.write(prefs,bytes(original));
    GeckoTlsProfile.Preparation preparation=GeckoTlsProfile.prepare(path.toFile(),profile,GeckoTlsSpec.of("tls13"));JSONObject evidence=preparation.evidence();check("Actual offline profile receipt binds before and committed non-TLS bytes",evidence.getBoolean("nonTlsPrefsBytePreserved")&&evidence.getInt("profileBytesBefore")==bytes(original).length&&evidence.getInt("profileBytesAfter")==bytes(expected).length&&evidence.getInt("removedOwnedBytes")==bytes(original).length-bytes(expected).length&&evidence.getString("nonTlsPrefsBeforeSha256").equals(evidence.getString("nonTlsPrefsAfterSha256")));check("Preparation receipt describes offline scope not a wire proof",evidence.getString("scope").equals("offline-two-owned-tls-preferences")&&!evidence.has("wireObservationVerified")&&evidence.getString("mode").equals("tls13"));check("Strict config records actual preserved base and changed final bytes",evidence.getBoolean("closedRouteConfigPrefixPreserved")&&!evidence.getString("configBeforeSha256").equals(evidence.getString("configAfterSha256")));check("Strict cold config appends only actual native4/4",Files.readString(path.resolve("gecko-browser.yaml")).equals(CLOSED+"  security.tls.version.min: 4\n  security.tls.version.max: 4\n"));check("Strict offline policy strips only owned old USER lines",Arrays.equals(Files.readAllBytes(prefs),bytes(expected)));
    base(path);Files.write(prefs,bytes(original));GeckoTlsProfile.prepare(path.toFile(),profile,GeckoTlsSpec.defaults());check("Default never invents native DEFAULT min/max or modifies CPU closed config",Files.readString(path.resolve("gecko-browser.yaml")).equals(CLOSED)&&Arrays.equals(Files.readAllBytes(prefs),bytes(expected)));
    Path user=profile.toPath().resolve("user.js");for(String override:new String[]{"user_pref(\"security.tls.version.min\", 4);","user_pref(\"security.tls.version.max\", 4);","user_pref(\"other\", 1);user_pref(\"security.tls.version.min\", 4);"}){Files.write(user,bytes(override));byte[] before=Files.readAllBytes(prefs);rejects("Untracked user.js override refuses cold activation",()->GeckoTlsProfile.prepare(path.toFile(),profile,GeckoTlsSpec.of("tls13")));check("Failed override leaves profile bytes untouched",Arrays.equals(before,Files.readAllBytes(prefs)));}Files.delete(user);
    Files.write(path.resolve("gecko-browser.yaml"),bytes(CLOSED+"  security.tls.version.min: 4\n"));rejects("Unexpected pre-existing TLS config is not silently replaced",()->GeckoTlsProfile.prepare(path.toFile(),profile,GeckoTlsSpec.defaults()));
    for(String leaf:new String[]{"gecko-browser","prefs.js","user.js","gecko-browser.yaml","pocket-tls-config.tmp","pocket-tls-prefs.tmp"}){
      Path owned=root.resolve("leaf-"+leaf.replace('.','-'));base(owned);Path selected=owned.resolve("gecko-browser");Files.createDirectories(selected);Path outside=root.resolve("outside-"+leaf.replace('.','-'));boolean directory=leaf.equals("gecko-browser");if(directory)Files.createDirectories(outside);else Files.write(outside,bytes("user_pref(\"unrelated\", 9);\n"));
      Path target=directory?selected:leaf.equals("gecko-browser.yaml")||leaf.equals("pocket-tls-config.tmp")?owned.resolve(leaf):selected.resolve(leaf);Files.deleteIfExists(target);Files.createSymbolicLink(target,outside);if(leaf.equals("pocket-tls-prefs.tmp"))Files.write(selected.resolve("prefs.js"),bytes("user_pref(\"security.tls.version.min\", 4);\n"));
      byte[] preserved=directory?new byte[0]:Files.readAllBytes(outside);rejects("Private profile/config leaf symlink rejected "+leaf,()->GeckoTlsProfile.prepare(owned.toFile(),selected.toFile(),GeckoTlsSpec.of("tls13")));check("Leaf failure preserves outside bytes "+leaf,directory||Arrays.equals(preserved,Files.readAllBytes(outside)));
    }
    Path foreign=root.resolve("foreign");base(foreign);rejects("Cross-profile path rejected",()->GeckoTlsProfile.prepare(foreign.toFile(),root.resolve("wrong").toFile(),GeckoTlsSpec.of("tls13")));
  }
  static final class FakeNative implements GeckoTlsController.NativeAccess {
    int configureCalls,readCalls;boolean alive=true;GeckoTlsSpec requested;Consumer<GeckoTlsController.Readback> configured,read;Consumer<Throwable> rejected;
    public boolean current(){return alive;}public void configure(GeckoTlsSpec mode,Consumer<GeckoTlsController.Readback> success,Consumer<Throwable> failure){configureCalls++;requested=mode;configured=success;rejected=failure;}
    public void read(Consumer<GeckoTlsController.Readback> success,Consumer<Throwable> failure){readCalls++;read=success;rejected=failure;}
  }
  static GeckoTlsController.Readback read(int min,int max,boolean user,boolean rfp){return new GeckoTlsController.Readback(min,max,min,max,user,false,rfp,true,true);}
  static final class Fixture {
    final TestContext context;final ChatSession session;final GeckoTlsController controller;GeckoTlsStore.State saved;GeckoTlsController.Boot boot;final Object runtime=new Object();final FakeNative nativeApi=new FakeNative();final List<Boolean> gate=new ArrayList<>();
    Fixture(String mode)throws Exception{context=new TestContext(root.resolve("controller"));session=new ChatSession(context);GeckoCpuProfile.prepare(GeckoCpuProfile.storage(context).root,new File(context.getNoBackupFilesDir(),"gecko-browser"),GeckoCpuSpec.of("2"));saved=GeckoTlsStore.load(context);if(!mode.equals("default"))saved=GeckoTlsStore.save(context,saved.identity,saved.revision,GeckoTlsSpec.of(mode));controller=new GeckoTlsController(session);}
    void drain(){session.handler.drain();session.environmentIo.drain();session.handler.drain();}
    void prepare(){MainQueue.ui=true;try{controller.prepareStartup(value->boot=value);}finally{MainQueue.ui=false;}}
    void attach(){controller.attachRuntime(boot,runtime,nativeApi,gate::add);}
    void ack(GeckoTlsController.Readback value){nativeApi.configured.accept(value);drain();}
  }
  static void positive()throws Exception{
    Fixture f=new Fixture("default");check("Null boot cannot claim runtime",!f.controller.claimRuntime(null));f.controller.attachRuntime(null,new Object(),new FakeNative(),v->check("Null attach explicit denial",!v));
    f.prepare();check("UI startup schedules only environmentIO",f.boot==null&&f.session.environmentIo.tasks.size()==1);f.session.environmentIo.drain();f.session.handler.drain();check("Boot captures immutable original default revision",f.boot!=null&&f.boot.desired.revision==f.saved.revision&&f.boot.desired.spec.isDefault());check("Controller retains actual pre-runtime preparation receipt",f.boot.preparation!=null&&f.boot.preparation.evidence().getBoolean("nonTlsPrefsBytePreserved")&&f.boot.preparation.evidence().getString("mode").equals("default"));
    f.controller.attachRuntime(f.boot,f.runtime,f.nativeApi,v->check("Unclaimed boot cannot attach",!v));check("Unclaimed boot writes no native pref",f.nativeApi.configureCalls==0);
    check("Exact runtime may be claimed once",f.controller.claimRuntime(f.boot)&&!f.controller.claimRuntime(f.boot));f.attach();check("New runtime admission waits for native receipt",!f.controller.readyFor(f.runtime)&&f.nativeApi.requested.isDefault());
    GeckoTlsStore.State strict=GeckoTlsStore.save(f.context,f.saved.identity,f.saved.revision,GeckoTlsSpec.of("tls13"));f.controller.desiredSaved(strict);check("Pending desired save performs no live native write or read",f.nativeApi.configureCalls==1&&f.nativeApi.readCalls==0);
    f.ack(read(3,4,false,false));check("Original default boot remains admitted despite saved pending strict",f.gate.equals(Arrays.asList(true))&&f.controller.readyFor(f.runtime));JSONObject status=f.controller.status();check("Desired and actual boot revisions remain separate",status.getString("desiredMode").equals("tls13")&&status.getString("activeBootMode").equals("default")&&status.getLong("activeBootRevision")==f.saved.revision&&status.getLong("desiredRevision")==strict.revision&&status.getBoolean("pendingColdStart"));
    check("Native ACK is never wire/fingerprint/QUIC or persistentSW proof",status.getBoolean("nativeSettingReadback")&&!status.getBoolean("wireObservationVerified")&&!status.getBoolean("fullTlsFingerprintEmulation")&&!status.getBoolean("quicWireVerified")&&!status.getBoolean("persistentWorkerColdStartVerified"));
    f.controller.desiredSaved(f.saved);check("Old async desired state cannot rewind cache",f.controller.snapshot()==strict);f.ack(read(3,4,false,false));check("Duplicate ACK cannot release admission twice",f.gate.size()==1);check("Wrong runtime cannot borrow ACK",!f.controller.readyFor(new Object()));
    f.controller.protectionWillChange();check("RFP transition retires cached protection snapshot",f.controller.status().isNull("rfpPriority"));f.controller.refreshNative();Consumer<GeckoTlsController.Readback> old=f.nativeApi.read;f.controller.protectionWillChange();f.controller.refreshNative();old.accept(read(3,4,false,false));f.session.handler.drain();check("Old native refresh cannot override newer protection boundary",f.controller.status().isNull("rfpPriority"));f.nativeApi.read.accept(read(3,4,false,true));f.session.handler.drain();check("Fresh native read records strongRFP without changing TLS range",f.controller.status().getBoolean("rfpPriority")&&f.controller.status().getInt("configuredMin")==3);
    f.controller.refreshNative();f.controller.retire(f.runtime);f.nativeApi.read.accept(read(3,4,false,false));f.session.handler.drain();check("Retirement rejects delayed native read",!f.controller.readyFor(f.runtime)&&!f.controller.status().getBoolean("nativeSettingReadback"));check("Retired owner cannot schedule further native work",!f.controller.acceptsNativeWork(f.runtime));
    boolean[] denied={false};new GeckoTlsController(f.session).prepareStartup(value->denied[0]=value==null);check("Warm process cannot prepare replacement cold boot",denied[0]);
  }
  static void scenario(String name)throws Exception{
    Fixture f=new Fixture(name.equals("default-alternate")?"default":"tls13");f.prepare();f.session.environmentIo.drain();f.session.handler.drain();check("Scenario boot prepared",f.boot!=null);check("Scenario runtime claimed",f.controller.claimRuntime(f.boot));f.attach();
    if(name.equals("timeout")){for(Runnable task:new ArrayList<>(f.session.handler.delayed))task.run();check("Missing native callback closes exactly once on deadline",f.gate.equals(Arrays.asList(false))&&!f.controller.readyFor(f.runtime));f.ack(read(4,4,false,false));check("Late ACK cannot undo timed-out native admission",f.gate.size()==1&&!f.controller.readyFor(f.runtime));return;}
    if(name.equals("deleted")){f.session.deleted=true;f.ack(read(4,4,false,false));check("Deleted owner cannot admit native ACK",f.gate.isEmpty()&&!f.controller.readyFor(f.runtime));return;}
    if(name.equals("catalog-changed")){f.context.catalog.current=new EnvironmentSpec.Identity(1,2,UUID.randomUUID().toString());f.ack(read(4,4,false,false));check("Catalog UUID/generation change fails final native admission",f.gate.equals(Arrays.asList(false))&&!f.controller.readyFor(f.runtime));return;}
    GeckoTlsController.Readback value=name.equals("old-protocol")?read(2,4,false,false):name.equals("user")?read(4,4,true,false):name.equals("strict-mismatch")?read(3,4,false,false):name.equals("default-alternate")?read(4,4,false,false):read(4,4,false,false);
    f.ack(value);boolean admitted=name.equals("strict")||name.equals("default-alternate");check("Native receipt mode USER and modern range validated "+name,f.gate.equals(Arrays.asList(admitted))&&f.controller.readyFor(f.runtime)==admitted);
    if(admitted){check("Actual acknowledged range reported without hardcoded default",f.controller.status().getInt("configuredMin")==value.configuredMin);f.controller.refreshNative();f.nativeApi.read.accept(read(3,4,true,false));f.session.handler.drain();check("Unexpected USER mutation invalidates new-request admission",!f.controller.readyFor(f.runtime));}
  }
  public static void main(String[] args)throws Exception{root=Paths.get(args[0]);Files.createDirectories(root);String mode=args[1];if(mode.equals("positive")){profile();positive();}else scenario(mode);System.out.println(J.obj("status","passed","passed",checks.size(),"total",checks.size(),"checks",new JSONArray(checks),"actualAndroidExecution",false,"actualGeckoExecution",false));}
}
